// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);

        // Deposit 1 wei
        vm.prank(alice);
        c.deposit{value: 1}();

        // First withdrawal: should succeed in both
        vm.prank(alice);
        c.withdrawAll();

        // Second withdrawal: in reference (C) it reverts because credit is 0; in mutant it succeeds again
        uint balanceBefore = address(c).balance;
        vm.prank(alice);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector));
        uint balanceAfter = address(c).balance;

        // In reference, call reverts → ok == false, balance unchanged
        // In mutant, call succeeds → ok == true, balance decreases by 1
        assertTrue(ok == false && balanceBefore == balanceAfter);
    }
}

