pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up Alice with 2 ether
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);

        // Alice deposits 1 ether
        vm.prank(alice);
        c.deposit{value: 1 ether}();

        // Alice withdraws all (first time), should succeed in both versions
        vm.prank(alice);
        c.withdrawAll();

        // Now Alice tries to withdraw again
        bool ok;
        vm.prank(alice);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts (ok == false), buggy version succeeds (ok == true)
        assertTrue(!ok, "Second withdrawAll should revert when credit is 0");
    }
}

